import { useState } from 'react';
import { Link } from 'react-router-dom';
import { useCart } from '../context/CartContext';
import { useAuth } from '../auth/AuthContext';
import { useOrders } from '../context/OrderContext';

function Cart() {
  const { items, removeFromCart, clearCart, totalPrice, totalCount } = useCart();
  const { member } = useAuth();
  const { createOrder } = useOrders();

  const [step, setStep] = useState('cart'); // 'cart' | 'payment' | 'success'
  const [slipUrl, setSlipUrl] = useState(null);
  const [slipNote, setSlipNote] = useState('');
  const [transferBank, setTransferBank] = useState('ธนาคารกสิกรไทย');
  const [errorMsg, setErrorMsg] = useState(null);
  const [submittedOrder, setSubmittedOrder] = useState(null);

  // อัปโหลดและแปลงสลิปเป็น Data URL
  function handleFileChange(e) {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!file.type.startsWith('image/')) {
      setErrorMsg('กรุณาเลือกไฟล์รูปภาพเท่านั้น (JPG, PNG)');
      return;
    }

    // จำกัดขนาดไฟล์ไม่เกิน 5MB
    if (file.size > 5 * 1024 * 1024) {
      setErrorMsg('ขนาดรูปภาพต้องไม่เกิน 5MB');
      return;
    }

    setErrorMsg(null);
    const reader = new FileReader();
    reader.onload = () => {
      setSlipUrl(reader.result);
    };
    reader.readAsDataURL(file);
  }

  // ส่งคำสั่งซื้อและสลิป
  function handleSubmitOrder(e) {
    e.preventDefault();
    if (!slipUrl) {
      setErrorMsg('กรุณาแนบรูปภาพสลิปการโอนเงินเพื่อยืนยันคำสั่งซื้อ');
      return;
    }

    try {
      const order = createOrder({
        items,
        totalAmount: totalPrice,
        slipUrl,
        slipNote,
        transferBank,
      });

      setSubmittedOrder(order);
      clearCart();
      setStep('success');
    } catch (err) {
      setErrorMsg(err.message || 'เกิดข้อผิดพลาดในการส่งคำสั่งซื้อ');
    }
  }

  // หน้าสำเร็จ
  if (step === 'success') {
    return (
      <div className="mx-auto max-w-2xl px-4 py-16 text-center md:px-6">
        <div className="rounded-2xl border border-amber-200 bg-white p-8 shadow-sm">
          <div className="mx-auto mb-4 flex h-16 w-16 items-center justify-center rounded-full bg-amber-100 text-3xl">
            ⏳
          </div>
          <span className="rounded-full bg-amber-50 border border-amber-200 px-3 py-1 text-xs font-bold text-amber-800">
            คำสั่งซื้อเลขที่: {submittedOrder?.id}
          </span>
          <h2 className="mt-3 text-2xl font-bold text-slate-900">ส่งหลักฐานการโอนเงินเรียบร้อยแล้ว!</h2>
          <p className="mt-2 text-slate-600 text-sm">
            ขอบคุณสำหรับการสั่งซื้อครับ คุณ {member?.displayName} ระบบได้ส่งข้อมูลให้แอดมินตรวจสอบแล้ว
            เมื่อแอดมินยืนยันยอดเงินสำเร็จ E-Book จะถูกเพิ่มเข้าสู่ชั้นหนังสือของคุณทันที
          </p>

          <div className="my-6 rounded-xl bg-slate-50 p-4 text-left text-xs">
            <div className="flex justify-between items-center pb-2 border-b border-slate-200">
              <span className="text-slate-500">สถานะคำสั่งซื้อ</span>
              <span className="font-bold text-amber-700 bg-amber-100 px-2 py-0.5 rounded">
                รอแอดมินตรวจสอบสลิป
              </span>
            </div>
            <div className="pt-2 flex justify-between items-center text-slate-700">
              <span>ยอดเงินรวมที่แจ้งโอน</span>
              <span className="font-bold text-sm text-slate-900">
                ฿{Number(submittedOrder?.totalAmount).toLocaleString('th-TH')}
              </span>
            </div>
          </div>

          <div className="flex flex-wrap justify-center gap-3">
            <Link
              to="/me/orders"
              className="rounded-lg bg-amber-500 px-5 py-2.5 text-sm font-bold text-white shadow-sm hover:bg-amber-600 transition"
            >
              📋 ติดตามสถานะคำสั่งซื้อ
            </Link>
            <Link
              to="/me/library"
              className="rounded-lg border border-slate-300 px-4 py-2.5 text-sm font-medium text-slate-700 hover:bg-slate-50 transition"
            >
              📚 ไปที่ชั้นหนังสือ
            </Link>
            <Link
              to="/books"
              className="rounded-lg border border-amber-200 px-4 py-2.5 text-sm font-medium text-amber-700 hover:bg-amber-50 transition"
            >
              เลือกดูหนังสือเพิ่ม
            </Link>
          </div>
        </div>
      </div>
    );
  }

  // หน้าเลือกวิธีชำระและแนบสลิป
  if (step === 'payment') {
    return (
      <div className="mx-auto max-w-3xl px-4 py-10 md:px-6">
        <button
          onClick={() => setStep('cart')}
          className="mb-4 text-xs font-semibold text-slate-500 hover:text-amber-600"
        >
          ← กลับไปตรวจสอบตะกร้าสินค้า
        </button>

        <h1 className="text-2xl font-bold text-slate-900">💳 โอนเงินชำระค่า E-Book และแนบสลิป</h1>
        <p className="mt-1 text-sm text-slate-500">
          กรุณาโอนเงินตามยอดที่ระบุ และแนบรูปภาพสลิปเพื่อส่งให้แอดมินตรวจสอบความถูกต้อง
        </p>

        <div className="mt-6 grid gap-6 md:grid-cols-2">
          {/* ข้อมูลบัญชีธนาคารสำหรับโอน */}
          <div className="rounded-2xl border border-emerald-200 bg-emerald-50/40 p-5 shadow-xs">
            <span className="rounded bg-emerald-100 px-2 py-0.5 text-xs font-bold text-emerald-800">
              บัญชีรับโอนเงิน
            </span>
            <h3 className="mt-2 text-lg font-bold text-slate-900">ธนาคารกสิกรไทย (KBANK)</h3>

            <div className="mt-4 space-y-2 text-sm text-slate-700">
              <div>
                <span className="text-xs text-slate-400 block">เลขที่บัญชี:</span>
                <span className="font-mono text-xl font-bold tracking-wider text-emerald-900">
                  098-2-34567-8
                </span>
              </div>
              <div>
                <span className="text-xs text-slate-400 block">ชื่อบัญชี:</span>
                <span className="font-semibold text-slate-900">บจก. นังสือกรับ ดิจิทัลบุ๊กส์</span>
              </div>
              <div>
                <span className="text-xs text-slate-400 block">หรือ สแกนพร้อมเพย์ (PromptPay):</span>
                <span className="font-mono font-medium text-slate-800">089-999-9999</span>
              </div>
            </div>

            <div className="mt-5 rounded-xl border border-emerald-200 bg-white p-3 text-center">
              <span className="text-xs text-slate-500">ยอดที่ต้องโอนสุทธิ</span>
              <p className="text-2xl font-black text-amber-600">
                ฿{totalPrice.toLocaleString('th-TH')}
              </p>
            </div>
          </div>

          {/* ฟอร์มแนบสลิป */}
          <form
            onSubmit={handleSubmitOrder}
            className="rounded-2xl border border-amber-100 bg-white p-5 shadow-sm space-y-4"
          >
            <h3 className="font-bold text-slate-900 text-sm">หลักฐานการชำระเงิน</h3>

            <div>
              <label className="block text-xs font-medium text-slate-700 mb-1">
                ช่องทาง / ธนาคารที่โอน
              </label>
              <select
                value={transferBank}
                onChange={(e) => setTransferBank(e.target.value)}
                className="w-full rounded-lg border border-slate-300 p-2 text-xs"
              >
                <option value="ธนาคารกสิกรไทย">ธนาคารกสิกรไทย (K PLUS)</option>
                <option value="ธนาคารไทยพาณิชย์">ธนาคารไทยพาณิชย์ (SCB EASY)</option>
                <option value="ธนาคารกรุงเทพ">ธนาคารกรุงเทพ (Bualuang mBanking)</option>
                <option value="ธนาคารกรุงไทย">ธนาคารกรุงไทย (Krungthai NEXT)</option>
                <option value="พร้อมเพย์ (PromptPay)">พร้อมเพย์ (PromptPay)</option>
                <option value="อื่นๆ">อื่นๆ</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-medium text-slate-700 mb-1">
                แนบสลิปโอนเงิน (รูปภาพ) *
              </label>
              <input
                type="file"
                accept="image/*"
                onChange={handleFileChange}
                required
                className="w-full text-xs text-slate-500 file:mr-2 file:rounded-lg file:border-0 file:bg-amber-50 file:px-3 file:py-2 file:text-xs file:font-semibold file:text-amber-700 hover:file:bg-amber-100"
              />
            </div>

            {slipUrl && (
              <div className="rounded-lg border border-slate-200 bg-slate-50 p-2">
                <p className="text-[11px] font-semibold text-slate-500 mb-1">ตัวอย่างสลิปที่แนบ:</p>
                <img
                  src={slipUrl}
                  alt="ตัวอย่างสลิป"
                  className="max-h-40 mx-auto rounded object-contain border"
                />
              </div>
            )}

            <div>
              <label className="block text-xs font-medium text-slate-700 mb-1">
                หมายเหตุเพิ่มเติม / วันเวลาที่โอน (ถ้ามี)
              </label>
              <input
                type="text"
                placeholder="เช่น โอนวันที่ 9 เวลา 14:20 น."
                value={slipNote}
                onChange={(e) => setSlipNote(e.target.value)}
                className="w-full rounded-lg border border-slate-300 p-2 text-xs"
              />
            </div>

            {errorMsg && (
              <p className="rounded bg-red-50 p-2 text-xs text-red-600 font-medium">{errorMsg}</p>
            )}

            <button
              type="submit"
              className="w-full rounded-xl bg-amber-500 py-3 text-center text-sm font-bold text-white shadow-md hover:bg-amber-600 transition active:scale-[0.99]"
            >
              ✓ ยืนยันการสั่งซื้อและส่งสลิป
            </button>
          </form>
        </div>
      </div>
    );
  }

  // หน้าแสดงรายการในตะกร้า (step === 'cart')
  return (
    <div className="mx-auto max-w-5xl px-4 py-10 md:px-6">
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900 md:text-3xl">🛒 ตะกร้าสินค้า E-Book</h1>
          <p className="mt-1 text-sm text-slate-500">
            มี {totalCount} เล่มในตะกร้าของคุณ (พร้อมดาวน์โหลด/อ่านได้ทันทีหลังแอดมินยืนยันสลิป)
          </p>
        </div>
        {totalCount > 0 && (
          <button
            onClick={clearCart}
            className="text-xs text-red-500 hover:text-red-700 underline"
          >
            ล้างตะกร้าทั้งหมด
          </button>
        )}
      </div>

      {totalCount === 0 ? (
        <div className="rounded-2xl border border-dashed border-amber-200 bg-white py-16 text-center">
          <p className="text-5xl">🛒</p>
          <h2 className="mt-4 text-lg font-semibold text-slate-800">ตะกร้าของคุณยังว่างอยู่</h2>
          <p className="mt-1 text-sm text-slate-500">เลือกดู E-Book น่าอ่านแล้วเพิ่มเข้าตะกร้าได้เลย</p>
          <Link
            to="/books"
            className="mt-6 inline-block rounded-lg bg-amber-500 px-5 py-2.5 text-sm font-medium text-white hover:bg-amber-600 transition shadow-sm"
          >
            ดูหนังสือทั้งหมด
          </Link>
        </div>
      ) : (
        <div className="grid gap-8 lg:grid-cols-3">
          {/* รายการหนังสือในตะกร้า */}
          <div className="space-y-4 lg:col-span-2">
            {items.map((item) => (
              <div
                key={item.id}
                className="flex gap-4 rounded-xl border border-amber-100 bg-white p-4 shadow-sm transition hover:shadow-md"
              >
                {item.coverUrl ? (
                  <img
                    src={item.coverUrl}
                    alt={item.title}
                    className="h-28 w-20 shrink-0 rounded-lg object-cover border border-slate-100"
                  />
                ) : (
                  <div className="grid h-28 w-20 shrink-0 place-items-center rounded-lg bg-amber-50 text-3xl">
                    📖
                  </div>
                )}

                <div className="flex flex-1 flex-col justify-between min-w-0">
                  <div>
                    <div className="flex items-start justify-between gap-2">
                      <Link
                        to={`/books/${item.id}`}
                        className="font-medium text-slate-900 hover:text-amber-600 truncate block text-base"
                      >
                        {item.title}
                      </Link>
                      <button
                        onClick={() => removeFromCart(item.id)}
                        className="text-slate-400 hover:text-red-500 text-sm p-1"
                        title="ลบออกจากตะกร้า"
                      >
                        ✕
                      </button>
                    </div>
                    <p className="text-xs text-slate-500 mt-0.5 truncate">{item.author}</p>
                    <div className="mt-2 flex items-center gap-2">
                      <span className="rounded-full bg-emerald-50 border border-emerald-200 px-2 py-0.5 text-xs text-emerald-700 font-medium">
                        E-Book (PDF/ePub)
                      </span>
                      {item.category && (
                        <span className="rounded-full bg-slate-100 px-2 py-0.5 text-xs text-slate-600 truncate">
                          {item.category}
                        </span>
                      )}
                    </div>
                  </div>

                  <div className="mt-3 flex items-center justify-between border-t border-slate-100 pt-2">
                    <span className="text-xs text-slate-400">เข้าถึงได้ตลอดชีพ</span>
                    <span className="text-base font-bold text-slate-900">
                      ฿{Number(item.priceTHB).toLocaleString('th-TH')}
                    </span>
                  </div>
                </div>
              </div>
            ))}
          </div>

          {/* สรุปรายการสั่งซื้อ */}
          <div className="h-fit rounded-xl border border-amber-100 bg-white p-5 shadow-sm">
            <h2 className="text-lg font-bold text-slate-900 mb-4">สรุปคำสั่งซื้อ</h2>
            <div className="space-y-3 text-sm text-slate-600">
              <div className="flex justify-between">
                <span>จำนวน E-Book ({totalCount} เล่ม)</span>
                <span>฿{totalPrice.toLocaleString('th-TH')}</span>
              </div>
              <div className="flex justify-between text-emerald-600">
                <span>ค่าจัดส่ง (ไฟล์ดิจิทัล)</span>
                <span>ฟรี</span>
              </div>
              <div className="border-t border-slate-200 pt-3 flex justify-between text-base font-bold text-slate-900">
                <span>ยอดชำระสุทธิ</span>
                <span className="text-xl text-amber-600">฿{totalPrice.toLocaleString('th-TH')}</span>
              </div>
            </div>

            <button
              onClick={() => setStep('payment')}
              className="mt-6 w-full rounded-xl bg-amber-500 py-3 text-center text-sm font-bold text-white shadow-md hover:bg-amber-600 transition active:scale-[0.99]"
            >
              ดำเนินการชำระเงินและแนบสลิป →
            </button>

            <p className="mt-3 text-center text-xs text-slate-400">
              🔒 โอนเงินและแนบสลิปเพื่อส่งให้แอดมินอนุมัติสิทธิ์ E-Book
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

export default Cart;
